package dev.veltraph.client.chocolate;
import java.math.BigDecimal;
import java.util.*;
/** Explicit same-retained-intent manual declaration, distinct from an acknowledged native purchase. */
final class ChocolateQueueManualReconciliation {
    record Plan(ChocolateFactoryRuntime.Selection selection,ChocolateFactoryRuntime.State state,BigDecimal knownSpent,BigDecimal manualDebit,BigDecimal nextManualDebit,ChocolateFactoryModule.Journal pending,ChocolateFactoryModule.Journal resolved,ChocolateFactoryObservation inspection,int hotbar) {}
    private ChocolateQueueManualReconciliation() {}
    static Plan prepare(ChocolateFactoryRuntime runtime,ChocolateFactoryProfile original,boolean currentProfileUnchanged,ChocolateFactoryModule.Journal pending,String declaredScope,boolean purchased,ChocolateFactoryObservation inspection,int hotbar,long now){
        var selected=runtime.selection();var state=runtime.state();
        if(selected==null||original==null||!currentProfileUnchanged||!original.scope().equals(declaredScope)||!selected.observation().scope().equals(declaredScope))throw new IllegalArgumentException("Retained original selection/profile and explicit original scope required; changed/restarted intent cannot be adopted");
        boolean knownAck=state==ChocolateFactoryRuntime.State.ACKNOWLEDGED&&pending!=null&&"ACKNOWLEDGED_UNPERSISTED".equals(pending.status());
        if(state!=ChocolateFactoryRuntime.State.UNKNOWN&&!knownAck||pending==null||pending.schema()!=1||!pending.scope().equals(declaredScope)||!Set.of("UNKNOWN","PENDING","ACKNOWLEDGED_UNPERSISTED").contains(pending.status())||pending.intentId().isBlank()||!pending.intentId().equals(selected.intentId())||!pending.upgrade().equals(selected.quote().id())||!pending.price().equals(selected.quote().price().toPlainString())||new BigDecimal(pending.spent()).compareTo(runtime.spent())!=0||new BigDecimal(pending.manualDeclaredDebit()).compareTo(runtime.manualDeclaredDebit())!=0)throw new IllegalArgumentException("Original unresolved journal/state/price/accounting does not match retained intent");
        var before=selected.observation();var q=selected.quote();
        if(inspection==null||!inspection.profileVerified()||!inspection.contextBound()||!inspection.scope().equals(declaredScope)||!inspection.title().equals(before.title())||!inspection.cursorEmpty()||!inspection.fresh(now,original.freshnessMillis())||inspection.session()!=before.session()||inspection.menu()!=before.menu()||inspection.screen()!=before.screen()||selected.selectedHotbar()<0||hotbar!=selected.selectedHotbar())throw new IllegalArgumentException("Fresh complete original native session/menu/profile/hotbar inspection required; labels are not persistent account identity");
        var protectedRows=before.rows().values().stream().filter(ChocolateFactoryObservation.Row::playerInventory).toList();if(inspection.rows().values().stream().filter(ChocolateFactoryObservation.Row::playerInventory).count()!=protectedRows.size()||protectedRows.stream().anyMatch(r->!Objects.equals(r,inspection.rows().get(r.slot()))))throw new IllegalArgumentException("Protected inventory/equipment changed");
        if(inspection.balance().isEmpty()||inspection.production().isEmpty()||inspection.capacity().isEmpty()||before.balance().isEmpty()||before.production().isEmpty())throw new IllegalArgumentException("Unknown balance/rate/capacity cannot resolve a queue result");
        var target=inspection.targets().get(q.id());if(target==null||target.slot()!=q.slot()||target.kind()!=q.kind())throw new IllegalArgumentException("Original target identity is unavailable");
        var elapsed=now-runtime.requestSentAtMillis();if(elapsed<0)throw new IllegalArgumentException("Inspection clock precedes original request");var income=before.production().get().max(inspection.production().get()).multiply(BigDecimal.valueOf(elapsed)).divide(BigDecimal.valueOf(1000));var lower=before.balance().get().subtract(purchased?q.price():BigDecimal.ZERO);var upper=lower.add(income).min(inspection.capacity().get());var balance=inspection.balance().get();
        if(balance.signum()<0||balance.compareTo(lower)<0||balance.compareTo(upper)>0||balance.compareTo(selected.reserve())<0)throw new IllegalArgumentException("Observed debit/balance/reserve contradicts the explicitly declared result");
        if(purchased){if(target.level()!=q.level()+1||Objects.equals(target.fullIdentity(),q.fullIdentity())||inspection.revision()==before.revision())throw new IllegalArgumentException("Purchased declaration requires exact fresh level+1 and changed target identity");}
        else{var unchanged=inspection.quotes().get(q.id());if(knownAck||target.level()!=q.level()||!Objects.equals(target.fullIdentity(),q.fullIdentity())||unchanged==null||unchanged.price().compareTo(q.price())!=0)throw new IllegalArgumentException("Not-purchased declaration requires unchanged original target and quote; known ACK cannot be denied");}
        BigDecimal manual=runtime.manualDeclaredDebit().add(purchased&&!knownAck?q.price():BigDecimal.ZERO);
        String reason="Manual "+(purchased?"purchased":"not-purchased")+" declaration for original scope="+declaredScope+"; captured account identity remains unproven; inspection revision="+inspection.revision()+"/millis="+inspection.observedMillis()+"/level="+target.level()+"/balance="+balance+"; native known spend="+runtime.spent()+"; manual declared Chocolate debit="+manual+"; no native ACK/UUID/Coin receipt manufactured; fresh deliberate selection required";
        var resolved=new ChocolateFactoryModule.Journal(1,declaredScope,original.verifiedOn(),"RECONCILED",q.id(),q.price().toPlainString(),runtime.spent().toPlainString(),reason,manual.toPlainString(),selected.intentId());return new Plan(selected,state,runtime.spent(),runtime.manualDeclaredDebit(),manual,pending,resolved,inspection,hotbar);
    }
    static boolean sameInspection(ChocolateFactoryObservation a,ChocolateFactoryObservation b){return a!=null&&b!=null&&a.session()==b.session()&&a.menu()==b.menu()&&a.screen()==b.screen()&&a.revision()==b.revision()&&a.rows().equals(b.rows())&&a.scope().equals(b.scope())&&a.title().equals(b.title())&&b.cursorEmpty()&&b.contextBound()&&b.profileVerified();}
}
